// GUARDS AGAINST THE VACUOUS PASS.
//
// `[].every(fn)` is `true`. `for (const x of []) assert(...)` runs zero assertions and the
// test reports success. So a check over a collection that is EMPTY BY ACCIDENT does not
// fail — it congratulates you, which is worse than no check at all, because the suite now
// carries a green tick where the coverage used to be.
//
// This is not hypothetical. During the 2026-08-02 monetization work, a check read:
//
//     const ess = cards.filter((c) => c.essential);
//     console.log('essentials full?', ess.every((c) => c.why) ? 'yes' : 'NO');   // "yes"
//
// `essential` was missing from CARD_COLUMNS, so `ess` was empty, `[].every()` was true,
// and the boundary reported "essentials are served in full" while all eight of them were
// being gated. The bug shipped past its own verification.
//
// THE RULE: every assertion that ranges over a collection must also assert the collection
// is not empty. Wrap the collection at the point it is bound and the guard cannot be
// forgotten at the point it is used — an empty corpus then throws at import, and every
// test in that file is honest by construction rather than by discipline.

/**
 * Assert a collection has members, and return it.
 *
 * @param {Array|Map|Set} coll
 * @param {string} name  what it is, for the failure message
 * @param {number} [min=1]  the floor; raise it where a known size is part of the contract
 */
export function nonEmpty(coll, name, min = 1) {
  const size = coll == null ? 0 : (typeof coll.length === 'number' ? coll.length : coll.size);
  if (!(size >= min)) {
    throw new Error(
      `${name} has ${size} members (need ${min}+). Every assertion ranging over it would `
      + 'pass vacuously, so this fails loudly instead. Fix what produced the empty '
      + 'collection — the checks that read it are reporting nothing.'
    );
  }
  return coll;
}
// The list item → counter card matcher.
//
// A shopper writes "blueberries" and gets the produce card attached to it. This is the
// second, more prominent path into the corpus; the Counter is untouched and remains the
// place you go when you deliberately want to look something up.
//
// THERE IS NO SECOND MATCHER HERE. Retrieval is `scoreEntries` from perimeter.js — the
// same function, the same floor, the same alias unit the ask path uses. What this module
// adds is the three things a LIST needs and a QUESTION does not: it skips the scope gate,
// it refuses kitchen-technique cards, and it collapses many items onto one card.
//
// WHY THE SCOPE GATE IS SKIPPED, DELIBERATELY. `inScope` exists to decide whether a
// SENTENCE is a grocery question, and every correction it has ever needed went the same
// direction — too tight, never too loose. A list item is not a sentence. "blueberries" has
// no grocery verb, no question word and no punctuation, which is the exact shape the gate
// has historically refused. There is also nothing for it to protect: a list item that
// matches nothing simply gets no card, which costs one KB scan of an in-memory array and
// zero model calls. The gate is a cost control on a path that has no cost.

import { scoreEntries, scorePool, pickEntries, perimeterKb, isPick, typeContradicts } from './perimeter.js';
import { kindFor, sectionForCategory } from './counterCards.js';
import { logCounterGap } from './counterGaps.js';

// The retrieval floor, stated in the unit both scorers share. See counterFloor.test.js —
// this is the same statement of the same rule, not a second one. `score >= CONFIDENT` is
// vacuous on the curated side (scoreEntries floors its own results at 2), so the alias
// check does the work; it is kept because it names the intent.
const CONFIDENT = 2;

// How many candidates to consider before giving up. Only matters when the leaders are home
// cards and we fall through past them.
const CANDIDATES = 3;

/* ═══════════════════════════ The five sections, plus frozen ═══════════════════════════

   THE COUNTER'S VOCABULARY WINS. The cart used to carry ten sections of its own — Produce,
   Meat & Seafood, Dairy & Eggs, Bakery, Pantry, Snacks, Frozen, Added, and two for live
   rows — mapped from PICK categories by a client-side table plus a regex that sniffed item
   names for dairy and frozen. That predates the corpus. It merged meat and seafood, which
   the counter splits, and it was a second index of the store that could drift from the one
   the knowledge is filed under.

   `label_terms` is NOT here. It is a reference section, not an aisle — nobody walks to it. */
export const LIST_SECTIONS = [
  { id: 'produce', title: 'Produce' },
  { id: 'meat', title: 'Meat' },
  { id: 'seafood', title: 'Seafood' },
  { id: 'eggs_dairy', title: 'Dairy & Eggs' },
  { id: 'bulk_pantry', title: 'Pantry & Bulk' },
  { id: 'frozen', title: 'Frozen' },
];

const SECTION_RANK = new Map(LIST_SECTIONS.map((s, i) => [s.id, i]));

/* FROZEN IS A LOCATION RULE ON TOP OF A KNOWLEDGE MATCH, and it is not a second matcher.

   The counter's sections file KNOWLEDGE: `frozen_vs_fresh_produce` is a produce card because
   it is about produce. But a cart section answers a different question — where in the
   building do I walk — and nobody walks to produce for frozen peas. Left alone, "frozen
   broccoli" sorted into Produce while "frozen pizza" (no card) fell to the trailing group,
   splitting one freezer across two places on the same list.

   So the card decides WHAT this item is about and this decides WHERE it is. One regex, on
   the name, applied after matching and never instead of it. */
const FROZEN = /\bfrozen\b/i;

/* A ROW MUST NOT DISPLAY A SECTION IT IS NOT SORTED INTO, and it used to do exactly that.

   Sorting read `cardSection`, which only exists when a card matched. The LABEL beside an
   unmatched row read the cart CATEGORY, which exists either way. So "Baby spinach" —
   category Produce, no card — sorted into "Everything else" and rendered the word Produce
   next to itself, three times on one twelve-item list. Two vocabularies again, which is
   the thing the counter-section reconciliation was supposed to have ended.

   This is the translation between them, and it is a translation rather than a second index
   because the OUTPUT is always a counter section id — the counter's vocabulary still wins.
   It is deliberately tiny: only the cart categories that name the SAME aisle a walk section
   names. 'Protein' spans meat, seafood and dairy, so it maps to nothing and stays a label;
   'Bakery' and 'Snacks' are not aisles the counter covers, so they stay labels too. That is
   what the mock showed as well — Sourdough sat under "Everything else" wearing "Bakery". */
const CATEGORY_SECTION = new Map([
  ['produce', 'produce'],
  ['dairy & eggs', 'eggs_dairy'],
]);

/** The walk section a cart CATEGORY names, or null if it does not name one. */
export function sectionForCartCategory(category) {
  return CATEGORY_SECTION.get(String(category || '').trim().toLowerCase()) || null;
}

/**
 * Where a row sits on the walk. Null means the trailing group.
 *
 * Prefers the STORED `cardSection` rather than re-deriving it, so a completed trip keeps
 * the order it was shopped in even after the corpus is refiled or a card is retired. The
 * cart category is a FALLBACK for rows no card claimed, never an override.
 */
export function sectionForItem(item) {
  if (!item) return null;
  if (FROZEN.test(item.name || '')) return 'frozen';
 * The card a written grocery item resolves to, or null.
 *
 * A HOME CARD NEVER ATTACHES TO A LIST ITEM, and it falls through rather than failing.
 * `kind === 'home'` is kitchen technique: what to do with food you already own. Writing
 * "lettuce" on a list matches `revive_greens` outright — "limp is water loss, not spoilage,
 * it comes back" — which is a true and useful card and the wrong answer to a shopper
 * standing in produce deciding what to buy. It is the same category error the projection
 * already prevents one step later by suppressing add-to-cart on home cards; this is that
 * rule applied one step earlier, where the item is created.
 *
 * @returns {{ slug:string, section:string|null, score:number }|null}
 */
export function matchItemToCard(name) {
  const q = String(name || '').trim();
  if (!q) return null;

  for (const c of scoreEntries(q, CANDIDATES)) {
    if (c.score < CONFIDENT || c.aliasScore <= 0) continue;
    if (kindFor(c.entry.id) === 'home') continue;
    if (NON_AISLE_SECTIONS.has(sectionForCategory(c.entry.category))) continue;
    if (!aliasNamesHead(q, c.entry)) continue;
    return {
      slug: c.entry.id,
      section: sectionForCategory(c.entry.category),
      score: c.score,
    };
  }
  return null;
}

/**
 * THE PICK FLOOR. Scored only for a row that ended with NO card — the caller enforces that
 * order (`attachCards`), never this function. Same alias-containment scorer, same gate, same
 * `stateContradicts` veto: a stateless produce pick reads as fresh, so "Canned tomatoes"
 * cannot pick up a fresh-tomato line. No home / label check is needed — `lintPick` refuses
 * a pick filed there. `pool` is injectable because the corpus holds no picks yet.
 *
 * @returns {{ id:string, line:string }|null}
 */
export function matchItemToPick(name, pool = perimeterKb.entries || []) {
  const q = String(name || '').trim();
  if (!q) return null;
  for (const c of scorePool(q, pickEntries(pool), CANDIDATES)) {
    if (c.score < CONFIDENT || c.aliasScore <= 0) continue;
    if (!c.entry.decision) continue;
    if (!aliasCoversRow(q, c.entry)) continue;
    return { id: c.entry.id, line: c.entry.decision };
  }
  return null;
}

// One trailing plural, folded so "carrot" and "carrots" are the same word. Both sides of
// every comparison go through it, so a word it mangles ("asparagus" → "asparagu") still
// agrees with itself.
const singular = (w) => w.replace(/(?:[sxz]|[cs]h|o)es$/, (m) => m.slice(0, -2)).replace(/(?<=[^s])s$/, '');
const rowWords = (s) =>
  String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/)
    .filter((w) => w && !/^\d+$/.test(w)).map(singular);

/**
 * THE ROW'S HEAD NOUN, AND EVERY OTHER WORD ON IT, MUST BE IN ONE ALIAS OF THE PICK.
 *
 * Containment alone let a bare-noun alias land on any compound row that carried it: "oat
 * milk" → the milk pick, whose line says the carton may hold raw milk; "corn tortillas" →
 * corn; "garlic powder" → garlic; "carrot cake" → carrots. The head-noun check (the Swift
 * fix for the one-word over-match, applied to the floor) is not enough on its own — "oat
 * milk", "coconut milk" and "lemon juice" share their head with the alias — so the rule is
 * the whole row: a modifier the pick's aliases never name is a different food. Cards get
 * the head-noun half of this (`aliasNamesHead`, below, and why only half); this is the
 * floor only. Numbers are ignored ("2 carrots" is carrots).
 */
function aliasCoversRow(name, entry) {
  const words = contentWords(name);
  if (!words.length) return false;
  return (entry.aliases || []).some((a) => {
    const has = new Set(rowWords(a));
    return words.every((w) => has.has(w));
  });
}

// The row's words with the inert modifiers stripped — the unit both guards read.
const contentWords = (name) => rowWords(name).filter((w) => !INERT_MODIFIERS.has(w));

/**
 * THE CARD-PATH GUARD: THE ROW'S HEAD NOUN MUST BE IN ONE ALIAS OF THE CARD.
 *
 * Cards run first, so `aliasCoversRow` on the floor never saw "carrot cake" once
 * `produce_root_vegetables` carried the bare alias "carrots": the card attached and the
 * shopper was told how to pick a root vegetable for a cake. Porting the whole-row rule to
 * cards was measured and rejected — card aliases are question-shaped, and multi-word rows
 * attach on SEVERAL aliases at once ("Brown or jasmine rice", "Bone-in, skin-on chicken
 * thighs", "cheddar cheese"); requiring every word in ONE alias cost eight correct rows
 * and one of the 26. The head noun is the product (the Swift fix for the one-word
 * over-match, CLAUDE.md): "carrot cake" is a cake, "garlic powder" is a powder, "broccoli
 * slaw" is a slaw, and no produce card's aliases name any of them. A row whose head IS the
 * card's noun — "organic carrots", "whole carrots", "2 carrots" — still lands.
 *
 * It is weaker than the floor's rule on purpose and only for the rows the floor's rule
 * misfiles; a compound whose head is the card's own noun ("oat milk" against a milk card)
 * is left to the card's aliases, as it was. Numbers and inert modifiers are ignored either
 * side, so "carrots, organic" reads carrots.
 *
 * THE HEAD IS TAKEN BEFORE A TRAILING QUALIFIER. "Peanut butter — just peanuts and salt" is
 * peanut butter; the words after the dash describe the label. Read whole, its last word was
 * "salt" and the row missed a card the bare name reaches. So the head is the last word of
 * the text BEFORE the first separator (dash, colon, semicolon, open paren). A row that puts
 * its product after one ("Organic: carrots") now misses instead of matching — the cheap
 * direction — and the probe pins that no shipping row does.
 *
 * THE COMMA IS NOT A SEPARATOR, measured: "Bone-in, skin-on chicken thighs" carries its
 * modifiers BEFORE the comma and the product after, and truncating there turned a correct
 * row into a miss. "Peanut butter, just peanuts and salt" therefore stays a miss — cheap,
 * and the pick that ships uses the dash.
 */
const QUALIFIER = /\s[—–-]\s|[:;(]/;
function aliasNamesHead(name, entry) {
  const words = contentWords(String(name || '').split(QUALIFIER, 1)[0]);
  if (!words.length) return false;
  const last = words[words.length - 1];
  return (entry.aliases || []).some((a) => rowWords(a).includes(last));
}
// authoring backlog with our words instead of theirs — which is the one thing that backlog
// exists to avoid.
const SHOPPER_AUTHORED = new Set(['user', 'imported']);

/**
 * Attach cards to every matchable row that has not been looked at yet.
 *
 * IDEMPOTENT BY CONSTRUCTION, exactly like attachOffers. `carded` is stamped on every row
 * this inspects — including the ones that matched nothing — so a reload, a save or a
 * check-off can never re-run the matcher over a row, and can never log its miss twice. A
 * gap counted once per save instead of once per item would make the authoring backlog a
 * measure of how often someone opened the app.
 *
 * @param {object} list  a sanitized list doc
 * @param {object} [opts]
 * @param {boolean} [opts.log=true]  write unmatched shopper-authored rows to counter_gaps
 * @param {object[]} [opts.pickPool]  KB entries to draw picks from; tests inject, prod reads the KB
 */
export function attachCards(list, { log = true, pickPool } = {}) {
  if (!list || !Array.isArray(list.items)) return list;

  let changed = false;
  const items = list.items.map((it) => {
    if (it.carded || !MATCHABLE.has(it.source)) return it;
    changed = true;

    const hit = cardForItem(it, pickPool);
    if (!hit) {
      // Cards first, picks only where no card attached. A pick is authored guidance, so a
      // row that gets one is not a gap.
      const pick = matchItemToPick(it.name, pickPool);
      if (pick) return { ...it, carded: true, pickLine: pick.line, pickId: pick.id };
      // The miss IS the product signal. Someone writing "kombucha" every week with nothing
      // behind it is the authoring queue writing itself out of real intent, which is the
      // one thing you cannot collect retroactively.
      if (log && SHOPPER_AUTHORED.has(it.source)) {
        logCounterGap({ question: it.name, outcome: 'miss', source: 'list' });
      }
      return { ...it, carded: true };
    }

    return {
      ...it,
      carded: true,
      cardSlug: hit.slug,
      // Denormalized on purpose: a completed trip has to keep its walking order even if the
      // card is later refiled or retired. Recomputing at render would let history shift.
      ...(hit.section ? { cardSection: hit.section } : {}),
    };
  });

  return changed ? { ...list, items } : list;
}

/* ═══════════════════════════ Collapse ═══════════════════════════ */

/**
 * Group matched rows by the card they share.
 *
 * MANY ITEMS ROUTINELY MAP TO ONE CARD — blueberries and strawberries both land on
 * `berries_picking`, pineapple and avocados both on `produce_ripeness_by_item`. Rendering
 * that card twice reads as a bug, so the card appears once with the items that summoned it
 * named against it.
 *
 * Returns rows in list order, each either a single uncarded item or a card with its items.
 * Order is taken from the FIRST item that claimed each card, so a collapse never moves a
 * row further than to the position of its earliest sibling.
 */
export function collapseByCard(items = []) {
  const out = [];
  const bySlug = new Map();
  for (const it of items) {
    if (!it?.cardSlug) {
      out.push({ slug: null, section: sectionForItem(it), items: [it] });
      continue;
    }
    const hit = bySlug.get(it.cardSlug);
    if (hit) {
      hit.items.push(it);
      continue;
    }
    const group = { slug: it.cardSlug, section: sectionForItem(it), items: [it] };
    bySlug.set(it.cardSlug, group);
    out.push(group);
  }
  return out;
}

/**
 * The whole list, grouped into walking order: the five counter sections, then frozen, then
 * everything with no card at all.

/**
 * Lint one pick entry. Empty is the passing state.
 * @returns {Array<{code:string, detail:string}>}
 */
// Zero first person (VOICE_SPEC). `I` is case-sensitive so "i" inside nothing trips;
// `us` is lowercase-only so a country of origin ("US grown") does not read as a pronoun.
const hasFirstPerson = (line) =>
  /\bI\b/.test(line) || /\b(me|my|mine|we|our|ours)\b/i.test(line) || /\bus\b/.test(line);

export function lintPick(entry) {
  const out = [];
  const fail = (code, detail) => out.push({ code, detail });
  const e = entry || {};

  // ── Required ──
  for (const f of ['id', 'title', 'category', 'decision']) {
    if (!String(e[f] || '').trim()) fail('PICK_FIELD_MISSING', `a pick needs ${f}`);
  }

  // ── Forbidden ──
  for (const f of Object.keys(e)) {
    if (PICK_FORBIDDEN_FIELDS.has(f)) {
      fail('PICK_FIELD_FORBIDDEN', `"${f}" is a card field — a pick is one sentence, not a card`);
    }
  }

  // ── The food, bare ──
  const title = String(e.title || '').trim();
  if (title && (words(title) > 4 || /[.!?,;:]/.test(title))) {
    fail('PICK_TITLE_NOT_BARE', `the title is the food, bare: "${title}"`);
  }

  // ── Filed under a counter ──
  const category = String(e.category || '').trim();
  if (category) {
    const section = sectionForCategory(category);
    if (!section) fail('PICK_CATEGORY_UNSECTIONED', `"${category}" maps to no counter section`);
    else if (section === NON_AISLE_SECTION) {
      fail('PICK_CATEGORY_NON_AISLE', `"${category}" files under ${section}, which no list row is ever sorted into`);
    }
  }

  // ── Aliases: bare nouns, both numbers ──
  const aliases = Array.isArray(e.aliases) ? e.aliases.map((a) => String(a || '').trim()).filter(Boolean) : [];
  if (aliases.length < 2) {
    fail('PICK_ALIASES_TOO_FEW', `a pick needs at least 2 bare-noun aliases; got ${aliases.length}`);
  }
  const notBare = aliases.filter((a) => !BARE_NOUN.test(a) || words(a) > MAX_PICK_ALIAS_WORDS);
  if (notBare.length) {
    fail(
      'PICK_ALIAS_NOT_BARE',
      `an alias is what a shopper types on a list — lowercase, ≤${MAX_PICK_ALIAS_WORDS} words: ${notBare.map((a) => `"${a}"`).join(', ')}`
    );
  }
  // A state-bearing pick ("Frozen peas") is about the frozen thing. `stateContradicts` is
  // silent when the ROW names no state, so a bare `peas` alias here would attach the frozen
  // line to a fresh row. Every alias carries the state, or the pick does not ship.
  if (title && statesIn(title).size) {
    const stateless = aliases.filter((a) => !statesIn(a).size);
    if (stateless.length) {
      fail(
        'PICK_ALIAS_DROPS_STATE',
        `the title names a state, so every alias must too: ${stateless.map((a) => `"${a}"`).join(', ')}`
      );
    }
  }
  const subjectless = aliases.filter(onlyModifiers);
  if (subjectless.length) {
    fail(
      'PICK_ALIAS_NO_SUBJECT',
      `an alias must name a food, not only describe one: ${subjectless.map((a) => `"${a}"`).join(', ')}`
    );
  }
  const set = new Set(aliases);
  const paired = aliases.some((a) => PLURALS_OF(a).some((p) => set.has(p)));
  if (aliases.length && !paired) {
    fail(
      'PICK_ALIASES_NO_NUMBER_PAIR',
      'aliases must carry a singular AND its plural (s / es / y→ies) — a list says "carrot" and "carrots" both'
    );
  }

  // ── The line ──
  const line = String(e.decision || '').trim();
  if (line) {
    // Exactly one sentence, closed with a period. Two sentences is a card's summary; a
    // fragment is a label.
    const terminals = (line.match(/[.!?](?=\s|$)/g) || []).length;
    if (terminals !== 1 || !line.endsWith('.')) {
      fail('PICK_LINE_NOT_ONE_SENTENCE', `exactly one sentence ending in a period: "${line}"`);
    }
    if (/\?/.test(line)) fail('PICK_LINE_QUESTION', `a pick states, it never asks: "${line}"`);
    if (words(line) > MAX_PICK_WORDS) {
      fail('PICK_LINE_TOO_LONG', `${words(line)}w > ${MAX_PICK_WORDS}: ${line}`);
    }
    if (hasFirstPerson(line)) {
      fail('PICK_LINE_FIRST_PERSON', `no I/me/my/we/our on any line Kristy speaks: "${line}"`);
    }
    if (/—/.test(line)) fail('PICK_LINE_EM_DASH', `no em-dash asides: "${line}"`);
    // No digits. A number is a measurement, and a measurement is a claim with a source a
    // list row cannot show. "Heavy for its size", never "over 200g".
    if (/\d/.test(line)) fail('PICK_LINE_DIGIT', `no digits on a pick line: "${line}"`);
    const vetoed = mechanicalVeto(line);
    if (vetoed) {
      fail(
        'PICK_LINE_NOT_MECHANICAL',
        `"${vetoed}" is about the body, not the food. A pick describes surface, weight, smell, ` +
          `color, firmness, date or a label word — what happens to the food, never to the shopper: "${line}"`
      );
    }

